// Actual private Probe boundary methods and data predicates; no MOOS Run/Notify.
#define main mavmoos_mission_execution_probe_main
#include "MissionExecutionProbe.cpp"
#undef main
#include <unistd.h>
namespace {
void require(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
struct Folder{std::filesystem::path path;explicit Folder(unsigned n):path(std::filesystem::temp_directory_path()/("mavmoos-auto-boundary-"+std::to_string(getpid())+"-"+std::to_string(n))){if(!std::filesystem::create_directory(path))throw std::runtime_error("fresh inert folder required");}~Folder(){std::filesystem::remove_all(path);}};
struct Writer{std::thread worker;Writer(const std::filesystem::path& path,const std::string& token,double delay):worker([=]{std::this_thread::sleep_for(std::chrono::duration<double>(delay));const auto temporary=path.string()+".inert.tmp";{std::ofstream file(temporary);file<<token;}std::filesystem::rename(temporary,path);}){}~Writer(){worker.join();}};
}
int main(){unsigned count=0;try{
 const std::string key="auto.completed";
 const auto test=[&](const char* name,const std::function<void(Probe&)>& fn){Folder dir(++count);Probe p;p.control=dir.path;p.runtime["nav_tx_accepted"]="0";const auto pub=mono();p.publication_attempts["run"]=pub;p.local_deadlines["run"]=pub+90;fn(p);std::cout<<"PASS "<<name<<'\n';};
 test("matching ACK keeps pumping before success",[&](Probe& p){const auto began=mono();const auto token=p.marker(key);unsigned pump=0;p.phaseAck(key,token,"run",began,began+.2,[&]{if(++pump==2){const auto temporary=p.control/(key+".inert.tmp");{std::ofstream file(temporary);file<<token;}std::filesystem::rename(temporary,p.control/(key+".ack"));}});require(pump==2,"mail/policy not pumped before coordinator ACK");});
 test("preexisting ACK rejected before marker",[&](Probe& p){std::ofstream(p.control/(key+".ack"))<<"old";bool failed=false;try{p.marker(key);}catch(const std::runtime_error&){failed=true;}require(failed&&!std::filesystem::exists(p.control/key),"preexisting ACK accepted");});
 test("foreign token rejected",[&](Probe& p){const auto began=mono();const auto token=p.marker(key);std::ofstream(p.control/(key+".ack"))<<"other";bool failed=false;try{p.phaseAck(key,token,"run",began,began+.1,[]{});}catch(const std::runtime_error&){failed=true;}require(failed,"foreign ACK accepted");});
 test("missing ACK has bounded fixed expiry",[&](Probe& p){const auto began=mono();const auto token=p.marker(key);bool failed=false;try{p.phaseAck(key,token,"run",began,began+.04,[]{});}catch(const std::runtime_error&){failed=true;}require(failed&&mono()-began<.25,"missing ACK wait unbounded");});
 test("slow pump cannot accept late ACK",[&](Probe& p){const auto began=mono();const auto token=p.marker(key);std::ofstream(p.control/(key+".ack"))<<token;bool failed=false;try{p.phaseAck(key,token,"run",began,began+.02,[]{std::this_thread::sleep_for(std::chrono::milliseconds(35));});}catch(const std::runtime_error&){failed=true;}require(failed,"pump renewed expiry");});
 test("wait ceiling clips original local request deadline",[&](Probe& p){const auto began=mono();p.local_deadlines["run"]=began+.04;const auto original=p.local_deadlines["run"];require(p.phaseDeadline("run",began)==original,"original expiry not clipped");const auto token=p.marker(key);Writer w(p.control/(key+".ack"),token,.08);bool failed=false;try{p.phaseAck(key,token,"run",began,p.phaseDeadline("run",began),[]{});}catch(const std::runtime_error&){failed=true;}require(failed&&p.local_deadlines["run"]==original,"late ACK renewed original request");});
 test("insufficient original lifetime cannot start dwell",[&](Probe& p){p.local_deadlines["run"]=mono()+.02;bool failed=false;try{p.observeWithin(3,"run",[]{return true;},"unused");}catch(const std::runtime_error&){failed=true;}require(failed,"dwell renewed request lifetime");});
 test("failed original operation prevents ready ACK success",[&](Probe& p){const auto began=mono();const auto token=p.marker(key);std::ofstream(p.control/(key+".ack"))<<token;p.latest["run"]={{"status","TIMED_OUT"},{"reason","original"}};bool failed=false;try{p.phaseAck(key,token,"run",began,began+.1,[&]{p.check("run");});}catch(const std::runtime_error&){failed=true;}require(failed,"operation timeout ignored");});
 test("returned pose uses declared physical region",[](Probe& p){const auto now=mono();p.have_home=true;p.home_lat=42.358456;p.home_lon=-71.087589;p.navigation={{"NAV_LAT",p.home_lat},{"NAV_LONG",p.home_lon},{"NAV_ALTITUDE",5}};for(const auto& value:p.navigation)p.navigation_at[value.first]=now;require(p.returnSampleRegion(p.home_lat,p.home_lon,now),"fresh home pose rejected");p.navigation["NAV_ALTITUDE"]=5.61;require(!p.returnSampleRegion(p.home_lat,p.home_lon,now),"height gate weakened");p.navigation["NAV_ALTITUDE"]=5;p.navigation["NAV_LAT"]+=3./111195.;require(!p.returnSampleRegion(p.home_lat,p.home_lon,now),"position gate weakened");});
 test("individually stale or future NAV samples rejected",[](Probe& p){const auto now=mono();p.have_home=true;p.home_lat=42.358456;p.home_lon=-71.087589;p.navigation={{"NAV_LAT",p.home_lat},{"NAV_LONG",p.home_lon},{"NAV_ALTITUDE",5}};for(const auto& value:p.navigation)p.navigation_at[value.first]=now;p.navigation_at["NAV_LAT"]=now-.51;require(!p.returnSampleRegion(p.home_lat,p.home_lon,now),"stale coordinate accepted");p.navigation_at["NAV_LAT"]=now+.01;require(!p.returnSampleRegion(p.home_lat,p.home_lon,now),"future coordinate accepted");});
 std::cout<<"{\"result\":\"PASS\",\"controls\":"<<count<<",\"scope\":\"actual Probe methods; unconnected client/files only, no MOOS Run/Notify/socket/native\"}\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}}
